// HasMonitor applies the HasEdge predicate on the "monitor" edge.
func HasMonitor() predicate.ChannelMonitorProbeAnomaly {
	return predicate.ChannelMonitorProbeAnomaly(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MonitorTable, MonitorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMonitorWith applies the HasEdge predicate on the "monitor" edge with a given conditions (other predicates).
func HasMonitorWith(preds ...predicate.ChannelMonitor) predicate.ChannelMonitorProbeAnomaly {
	return predicate.ChannelMonitorProbeAnomaly(func(s *sql.Selector) {
		step := newMonitorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ChannelMonitorProbeAnomaly) predicate.ChannelMonitorProbeAnomaly {
	return predicate.ChannelMonitorProbeAnomaly(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ChannelMonitorProbeAnomaly) predicate.ChannelMonitorProbeAnomaly {
	return predicate.ChannelMonitorProbeAnomaly(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ChannelMonitorProbeAnomaly) predicate.ChannelMonitorProbeAnomaly {
	return predicate.ChannelMonitorProbeAnomaly(sql.NotPredicates(p))
}
